    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xDeEa8fdB85503531F6A5D2A036d3268bD7C06c09;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed beyond getting CLE tokens
        // The attacker needs at least 1 CLE token to call approve()
        deal(TARGET, attacker, 1 * 10**9); // Give attacker 1 CLE token (9 decimals)
    }

    // ─── Exploit ─────────────────────────────────────────────
